def _verdict_domain(v: CellVerdict) -> str:
    """Map a verdict to its verification domain."""
    tool = v.tool_used.lower()
    # Check PATTERN first — NK tools must not fall through to CODE
    if any(k in tool for k in ("dedup", "false_positive", "anomaly", "similar", "intra_round")):
        return _DOMAIN_PATTERN
    if any(k in tool for k in ("ct", "falsif", "code", "snippet")):
        return _DOMAIN_CODE
    if any(k in tool for k in ("sympy", "z3", "smt", "stats")):
        return _DOMAIN_MATH
    return _DOMAIN_PATTERN  # default to lowest-impact domain
